using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Topstar.Application.Operations;
using Topstar.Application.Schedules;
using Topstar.Application.Shipments;
using Topstar.Infrastructure.Entities;
using Topstar.Infrastructure.Notifications;
using Topstar.Infrastructure.Persistence;
namespace Topstar.Infrastructure.Operations;

public sealed class OperationsAdminService(TopstarDbContext db):IOperationsAdminService
{
    public async Task<OperationalQueueCount> GetQueueCountAsync(CancellationToken ct=default)
    {
        var rows=await db.OperationalEscalations.AsNoTracking()
            .Where(x=>x.Status!="Resolved")
            .GroupBy(_=>1)
            .Select(g=>new OperationalQueueCount(g.Count(),g.Count(x=>x.Severity=="Critical"),g.Count(x=>x.Status=="Open")))
            .FirstOrDefaultAsync(ct);
        return rows??new OperationalQueueCount(0,0,0);
    }

    public async Task<OperationsAdminDashboard> GetCampaignDashboardAsync(Guid campaignId,CancellationToken ct=default)
    {
        var dashboard=await GetDashboardAsync(ct);
        var shipmentIds=await(from s in db.Shipments.AsNoTracking()
                              join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id
                              where p.CampaignId==campaignId
                              select s.Id).ToListAsync(ct);
        var scheduleIds=await(from s in db.Schedules.AsNoTracking()
                              join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id
                              where p.CampaignId==campaignId
                              select s.Id).ToListAsync(ct);
        var submissionIds=await(from s in db.Submissions.AsNoTracking()
                                join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id
                                where p.CampaignId==campaignId
                                select s.Id).ToListAsync(ct);
        var disputeIds=await(from d in db.DisputeCases.AsNoTracking()
                             join p in db.Participations.AsNoTracking() on d.ParticipationId equals p.Id
                             where p.CampaignId==campaignId
                             select d.Id).ToListAsync(ct);

        return new OperationsAdminDashboard(
            dashboard.ShipmentIssues.Where(x=>shipmentIds.Contains(x.ShipmentId)).ToList(),
            dashboard.ScheduleAttention.Where(x=>scheduleIds.Contains(x.ScheduleId)).ToList(),
            dashboard.SubmissionEscalations.Where(x=>submissionIds.Contains(x.SubmissionId)).ToList(),
            [],
            dashboard.BrandReviewEscalations.Where(x=>submissionIds.Contains(x.SubmissionId)).ToList(),
            [],
            dashboard.DisputeEscalations.Where(x=>disputeIds.Contains(x.DisputeCaseId)).ToList(),
            [],
            []);
    }

    public async Task<OperationsAdminDashboard> GetDashboardAsync(CancellationToken ct=default)
    {
        var (brandReviews,brandReviewRuns)=await LoadBrandReviewDashboardAsync(ct);
        var shipmentRows=await(from s in db.Shipments.AsNoTracking() join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where s.Status==ShipmentStatuses.Issue orderby s.UpdatedAtUtc select new{s.Id,c.Title,BrandName=b.CompanyName,KocName=k.DisplayName,s.Carrier,s.TrackingCode,s.IssueNote,Updated=s.UpdatedAtUtc??s.CreatedAtUtc}).ToListAsync(ct);
        var shipmentIds=shipmentRows.Select(x=>x.Id).ToArray(); var sh=await db.ShipmentStatusHistories.AsNoTracking().Where(x=>shipmentIds.Contains(x.ShipmentId)).OrderBy(x=>x.CreatedAtUtc).ToListAsync(ct); var shMap=sh.GroupBy(x=>x.ShipmentId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<ShipmentHistoryItem>)g.Select(x=>new ShipmentHistoryItem(x.FromStatus,x.ToStatus,x.Note,x.CreatedAtUtc)).ToList());
        var evidenceRows=await db.ShipmentEvidence.AsNoTracking().Where(x=>shipmentIds.Contains(x.ShipmentId)).OrderBy(x=>x.CreatedAtUtc).ToListAsync(ct);var evidenceMap=evidenceRows.GroupBy(x=>x.ShipmentId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<ShipmentEvidenceItem>)g.Select(x=>new ShipmentEvidenceItem(x.Id,x.EvidenceType,x.FileUrl,x.Caption,x.ActorRole,x.CreatedAtUtc)).ToList());
        var trackingRows=await db.ShipmentTrackingEvents.AsNoTracking().Where(x=>shipmentIds.Contains(x.ShipmentId)).OrderByDescending(x=>x.OccurredAtUtc).ToListAsync(ct);var trackingMap=trackingRows.GroupBy(x=>x.ShipmentId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<ShipmentTrackingItem>)g.Select(x=>new ShipmentTrackingItem(x.Id,x.EventCode,x.Description,x.Location,x.OccurredAtUtc,x.Source,x.CreatedAtUtc)).ToList());
        var issues=shipmentRows.Select(x=>new ShipmentIssueAdminItem(x.Id,x.Title,x.BrandName,x.KocName,x.Carrier,x.TrackingCode,x.IssueNote??"Không có mô tả",x.Updated,shMap.GetValueOrDefault(x.Id,[]),evidenceMap.GetValueOrDefault(x.Id,[]),trackingMap.GetValueOrDefault(x.Id,[]))).ToList();

        var now=DateTime.UtcNow;
        var scheduleRows=await(from s in db.Schedules.AsNoTracking() join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where s.Status!=ScheduleStatuses.Cancelled && (s.RescheduleCount>=2 || ((s.Status==ScheduleStatuses.Proposed||s.Status==ScheduleStatuses.Rescheduled)&&s.StartsAtUtc<=now)) orderby s.StartsAtUtc select new{s.Id,c.Title,BrandName=b.CompanyName,KocName=k.DisplayName,s.Status,s.StartsAtUtc,s.EndsAtUtc,s.RescheduleCount}).ToListAsync(ct);
        var scheduleIds=scheduleRows.Select(x=>x.Id).ToArray(); var sch=await db.ScheduleStatusHistories.AsNoTracking().Where(x=>scheduleIds.Contains(x.ScheduleId)).OrderBy(x=>x.CreatedAtUtc).ToListAsync(ct); var schMap=sch.GroupBy(x=>x.ScheduleId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<ScheduleHistoryItem>)g.Select(x=>new ScheduleHistoryItem(x.FromStatus,x.ToStatus,x.StartsAtUtc,x.EndsAtUtc,x.Note,x.CreatedAtUtc)).ToList());
        var attention=scheduleRows.Select(x=>new ScheduleAttentionAdminItem(x.Id,x.Title,x.BrandName,x.KocName,x.Status,x.StartsAtUtc,x.EndsAtUtc,x.RescheduleCount,x.StartsAtUtc<=now&&x.Status!=ScheduleStatuses.Confirmed?"Đã quá giờ nhưng chưa xác nhận":$"Đã đổi lịch {x.RescheduleCount} lần",schMap.GetValueOrDefault(x.Id,[]))).ToList();
        var escalationRows=await(from e in db.OperationalEscalations.AsNoTracking() join s in db.Submissions.AsNoTracking() on e.SourceEntityId equals s.Id join d in db.CampaignDeliverables.AsNoTracking() on s.DeliverableId equals d.Id join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where e.RuleCode=="SUBMISSION_OVERDUE"&&e.SourceEntityType=="Submission"&&e.Status!="Resolved" orderby e.Severity=="Critical"?0:1,e.FirstDetectedAtUtc select new{Escalation=e,Submission=s,c.Title,BrandName=b.CompanyName,KocName=k.DisplayName,d.DeliverableType,d.DueDateUtc}).ToListAsync(ct);
        var escalationIds=escalationRows.Select(x=>x.Escalation.Id).ToArray();var eh=await(from h in db.OperationalEscalationHistories.AsNoTracking() join u in db.Users.AsNoTracking() on h.ActorUserId equals u.Id where escalationIds.Contains(h.EscalationId) orderby h.CreatedAtUtc select new{History=h,Actor=u.Email}).ToListAsync(ct);var ehMap=eh.GroupBy(x=>x.History.EscalationId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<EscalationHistoryItem>)g.Select(x=>new EscalationHistoryItem(x.History.FromStatus,x.History.ToStatus,x.History.Note,x.Actor,x.History.CreatedAtUtc)).ToList());
        var escalations=escalationRows.Where(x=>x.DueDateUtc.HasValue).Select(x=>new SubmissionEscalationAdminItem(x.Escalation.Id,x.Submission.Id,x.Title,x.BrandName,x.KocName,x.DeliverableType,x.DueDateUtc!.Value,x.Submission.Status,x.Escalation.Severity,x.Escalation.Status,x.Escalation.FirstDetectedAtUtc,x.Escalation.LastDetectedAtUtc,ehMap.GetValueOrDefault(x.Escalation.Id,[]))).ToList();
        var scanRuns=await(from r in db.OperationalScanRuns.AsNoTracking() join u in db.Users.AsNoTracking() on r.ActorUserId equals u.Id where r.RuleCode=="SUBMISSION_OVERDUE" orderby r.CompletedAtUtc descending select new OperationalScanRunItem(r.StartedAtUtc,r.CompletedAtUtc,r.DetectedCount,r.CreatedCount,r.ResolvedCount,r.CriticalCount,u.Email)).Take(10).ToListAsync(ct);
        var disputeRows=await(from e in db.OperationalEscalations.AsNoTracking() join d in db.DisputeCases.AsNoTracking() on e.DisputeCaseId equals d.Id where e.RuleCode=="DISPUTE_SLA"&&e.Status!="Resolved" orderby e.Severity=="Critical"?0:1,e.FirstDetectedAtUtc select new{Escalation=e,Dispute=d}).ToListAsync(ct);var disputeIds=disputeRows.Select(x=>x.Escalation.Id).ToArray();var deh=await(from h in db.OperationalEscalationHistories.AsNoTracking() join u in db.Users.AsNoTracking() on h.ActorUserId equals u.Id where disputeIds.Contains(h.EscalationId) orderby h.CreatedAtUtc select new{History=h,Actor=u.Email}).ToListAsync(ct);var dehMap=deh.GroupBy(x=>x.History.EscalationId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<EscalationHistoryItem>)g.Select(x=>new EscalationHistoryItem(x.History.FromStatus,x.History.ToStatus,x.History.Note,x.Actor,x.History.CreatedAtUtc)).ToList());
        var disputeEscalations=disputeRows.Select(x=>new DisputeEscalationAdminItem(x.Escalation.Id,x.Dispute.Id,x.Dispute.Subject,x.Dispute.Category,x.Dispute.Priority,x.Dispute.Status,x.Escalation.Severity,x.Escalation.Status,x.Escalation.LastDetectedAtUtc,x.Escalation.FirstDetectedAtUtc,dehMap.GetValueOrDefault(x.Escalation.Id,[]))).ToList();var disputeRuns=await(from r in db.OperationalScanRuns.AsNoTracking() join u in db.Users.AsNoTracking() on r.ActorUserId equals u.Id where r.RuleCode=="DISPUTE_SLA" orderby r.CompletedAtUtc descending select new OperationalScanRunItem(r.StartedAtUtc,r.CompletedAtUtc,r.DetectedCount,r.CreatedCount,r.ResolvedCount,r.CriticalCount,u.Email)).Take(10).ToListAsync(ct);
        var policyRows=await db.OperationalSlaPolicies.AsNoTracking().OrderBy(x=>x.RuleCode).ToListAsync(ct);var policyIds=policyRows.Select(x=>x.Id).ToArray();var policyHistoryRows=await(from h in db.OperationalSlaPolicyHistories.AsNoTracking() join u0 in db.Users.AsNoTracking() on h.ActorUserId equals u0.Id into actors from u in actors.DefaultIfEmpty() where policyIds.Contains(h.PolicyId) orderby h.CreatedAtUtc descending select new{History=h,Actor=u==null?"Hệ thống":u.Email}).ToListAsync(ct);var policyHistoryMap=policyHistoryRows.GroupBy(x=>x.History.PolicyId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<SlaPolicyHistoryItem>)g.Select(x=>new SlaPolicyHistoryItem(x.History.FromHighAfterHours,x.History.FromCriticalAfterHours,x.History.FromIsActive,x.History.ToHighAfterHours,x.History.ToCriticalAfterHours,x.History.ToIsActive,x.History.Note,x.Actor,x.History.CreatedAtUtc)).ToList());
        var updaterIds=policyRows.Where(x=>x.UpdatedByUserId.HasValue).Select(x=>x.UpdatedByUserId!.Value).Distinct().ToArray();var updaterMap=await db.Users.AsNoTracking().Where(x=>updaterIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Email,ct);var policies=policyRows.Select(x=>new SlaPolicyAdminItem(x.Id,x.RuleCode,x.RuleCode switch{"SUBMISSION_OVERDUE"=>"KOC nộp bài quá hạn","BRAND_REVIEW_SLA"=>"Brand chậm duyệt bài",_=>"Dispute không có hoạt động"},x.HighAfterHours,x.CriticalAfterHours,x.IsActive,x.UpdatedAtUtc??x.CreatedAtUtc,x.UpdatedByUserId.HasValue?updaterMap.GetValueOrDefault(x.UpdatedByUserId.Value,"Không xác định"):"Hệ thống",policyHistoryMap.GetValueOrDefault(x.Id,[]))).ToList();
        return new(issues,attention,escalations,scanRuns,brandReviews,brandReviewRuns,disputeEscalations,disputeRuns,policies);
    }

    private async Task<(IReadOnlyList<SubmissionEscalationAdminItem>,IReadOnlyList<OperationalScanRunItem>)> LoadBrandReviewDashboardAsync(CancellationToken ct)
    {
        var rows=await(from e in db.OperationalEscalations.AsNoTracking() join s in db.Submissions.AsNoTracking() on e.SubmissionId equals s.Id join d in db.CampaignDeliverables.AsNoTracking() on s.DeliverableId equals d.Id join p in db.Participations.AsNoTracking() on s.ParticipationId equals p.Id join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where e.RuleCode=="BRAND_REVIEW_SLA"&&e.Status!="Resolved" orderby e.Severity=="Critical"?0:1,e.FirstDetectedAtUtc select new{Escalation=e,Submission=s,c.Title,BrandName=b.CompanyName,KocName=k.DisplayName,d.DeliverableType}).ToListAsync(ct);var ids=rows.Select(x=>x.Escalation.Id).ToArray();var histories=await(from h in db.OperationalEscalationHistories.AsNoTracking() join u in db.Users.AsNoTracking() on h.ActorUserId equals u.Id where ids.Contains(h.EscalationId) orderby h.CreatedAtUtc select new{History=h,Actor=u.Email}).ToListAsync(ct);var map=histories.GroupBy(x=>x.History.EscalationId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<EscalationHistoryItem>)g.Select(x=>new EscalationHistoryItem(x.History.FromStatus,x.History.ToStatus,x.History.Note,x.Actor,x.History.CreatedAtUtc)).ToList());var items=rows.Where(x=>x.Submission.SubmittedAtUtc.HasValue).Select(x=>new SubmissionEscalationAdminItem(x.Escalation.Id,x.Submission.Id,x.Title,x.BrandName,x.KocName,x.DeliverableType,x.Submission.SubmittedAtUtc!.Value,x.Submission.Status,x.Escalation.Severity,x.Escalation.Status,x.Escalation.FirstDetectedAtUtc,x.Escalation.LastDetectedAtUtc,map.GetValueOrDefault(x.Escalation.Id,[]))).ToList();var runs=await(from r in db.OperationalScanRuns.AsNoTracking() join u in db.Users.AsNoTracking() on r.ActorUserId equals u.Id where r.RuleCode=="BRAND_REVIEW_SLA" orderby r.CompletedAtUtc descending select new OperationalScanRunItem(r.StartedAtUtc,r.CompletedAtUtc,r.DetectedCount,r.CreatedCount,r.ResolvedCount,r.CriticalCount,u.Email)).Take(10).ToListAsync(ct);return(items,runs);
    }

    public async Task<OperationsResult> ResolveShipmentAsync(Guid admin,Guid id,string decision,string note,CancellationToken ct=default)
    {
        decision=Clean(decision)??"";note=Clean(note)??"";if(decision is not(ShipmentStatuses.InTransit or ShipmentStatuses.Returned)||!ShipmentEvidenceRules.IsValidIssueNote(note))return Fail("Chọn tiếp tục giao hoặc hoàn hàng và nhập cách xử lý từ 10 đến 1.000 ký tự.");
        var row=await(from s in db.Shipments join p in db.Participations on s.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id join k in db.KocProfiles on p.KocProfileId equals k.Id where s.Id==id select new{Shipment=s,BrandUser=b.UserId,KocUser=k.UserId}).FirstOrDefaultAsync(ct);
        if(row is null)return Fail("Không tìm thấy vận đơn.");if(row.Shipment.Status!=ShipmentStatuses.Issue)return Fail("Sự cố đã được xử lý ở phiên khác.");var now=DateTime.UtcNow;row.Shipment.Status=decision;row.Shipment.IssueNote=null;row.Shipment.UpdatedAtUtc=now;
        db.ShipmentStatusHistories.Add(new(){Id=Guid.NewGuid(),ShipmentId=id,FromStatus=ShipmentStatuses.Issue,ToStatus=decision,Note=$"Admin: {note}",ActorUserId=admin,CreatedAtUtc=now});Notify(row.BrandUser,"BRAND","Operations","Admin đã xử lý sự cố vận chuyển",note,"Shipment",id,now);Notify(row.KocUser,"KOC","Operations","Admin đã xử lý sự cố vận chuyển",note,"Shipment",id,now);Audit(admin,"Shipment",id,"AdminResolve",new{Decision=decision,Note=note},now);
        try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Fail("Trạng thái vừa thay đổi. Vui lòng tải lại.");}return Ok(decision==ShipmentStatuses.Returned?"Đã ghi nhận hoàn hàng.":"Đã cho phép tiếp tục giao.");
    }

    public async Task<OperationsResult> CancelScheduleAsync(Guid admin,Guid id,string reason,CancellationToken ct=default)
    {
        reason=Clean(reason)??"";if(reason.Length is 0 or >1000)return Fail("Nhập lý do can thiệp, tối đa 1.000 ký tự.");var row=await(from s in db.Schedules join p in db.Participations on s.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id join k in db.KocProfiles on p.KocProfileId equals k.Id where s.Id==id select new{Schedule=s,BrandUser=b.UserId,KocUser=k.UserId}).FirstOrDefaultAsync(ct);
        if(row is null)return Fail("Không tìm thấy lịch.");if(!ScheduleTransitions.CanCancel(row.Schedule.Status))return Fail("Lịch không còn cho phép hủy.");var now=DateTime.UtcNow;var from=row.Schedule.Status;var isLate=ScheduleTransitions.IsLateCancellation(from,row.Schedule.StartsAtUtc,now);row.Schedule.Status=ScheduleStatuses.Cancelled;row.Schedule.IsLateCancellation=isLate;row.Schedule.LateCancellationThresholdHours=isLate?ScheduleTransitions.LateCancellationHours:null;row.Schedule.CancelledAtUtc=now;row.Schedule.CancelledByUserId=admin;row.Schedule.UpdatedAtUtc=now;if(isLate)reason=$"[Hủy sát giờ ≤ {ScheduleTransitions.LateCancellationHours}h] {reason}";
        db.ScheduleStatusHistories.Add(new(){Id=Guid.NewGuid(),ScheduleId=id,FromStatus=from,ToStatus=ScheduleStatuses.Cancelled,StartsAtUtc=row.Schedule.StartsAtUtc,EndsAtUtc=row.Schedule.EndsAtUtc,Note=$"Admin: {reason}",ActorUserId=admin,CreatedAtUtc=now});Notify(row.BrandUser,"BRAND","Operations","Admin đã hủy lịch booking",reason,"Schedule",id,now);Notify(row.KocUser,"KOC","Operations","Admin đã hủy lịch booking",reason,"Schedule",id,now);Audit(admin,"Schedule",id,"AdminCancel",new{FromStatus=from,Reason=reason},now);
        try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Fail("Trạng thái vừa thay đổi. Vui lòng tải lại.");}return Ok("Đã hủy lịch và thông báo cho hai bên.");
    }
    public async Task<OperationsResult> ScanSubmissionOverdueAsync(Guid admin,CancellationToken ct=default)
    {
        var policy=await db.OperationalSlaPolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.RuleCode=="SUBMISSION_OVERDUE",ct);if(policy is null)return Fail("Chưa có cấu hình SLA cho submission. Vui lòng chạy migration 47.");if(!policy.IsActive)return Fail("Rule submission quá hạn đang tạm dừng.");var now=DateTime.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);
        var highCutoffUtc=now.AddHours(-policy.HighAfterHours);var overdue=await(from s in db.Submissions join d in db.CampaignDeliverables on s.DeliverableId equals d.Id join p in db.Participations on s.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id join k in db.KocProfiles on p.KocProfileId equals k.Id where d.DueDateUtc.HasValue&&d.DueDateUtc<=highCutoffUtc&&c.Status=="InProgress"&&(s.Status=="NotSubmitted"||s.Status=="NeedRevision"||s.Status=="Submitted") select new{Submission=s,Due=d.DueDateUtc!.Value,Campaign=c,BrandUser=b.UserId,KocUser=k.UserId}).ToListAsync(ct);
        var overdueIds=overdue.Select(x=>x.Submission.Id).ToHashSet();var existing=await db.OperationalEscalations.Where(x=>x.RuleCode=="SUBMISSION_OVERDUE"&&x.SourceEntityType=="Submission").ToListAsync(ct);var created=0;var resolved=0;
        foreach(var row in overdue){var escalation=existing.FirstOrDefault(x=>x.SourceEntityId==row.Submission.Id);var severity=now-row.Due>=TimeSpan.FromHours(policy.CriticalAfterHours)?"Critical":"High";if(escalation is null){escalation=new(){Id=Guid.NewGuid(),RuleCode="SUBMISSION_OVERDUE",SourceEntityType="Submission",SourceEntityId=row.Submission.Id,SubmissionId=row.Submission.Id,Severity=severity,Status="Open",FirstDetectedAtUtc=now,LastDetectedAtUtc=now,CreatedAtUtc=now};db.OperationalEscalations.Add(escalation);History(escalation.Id,null,"Open",$"Quá hạn từ {row.Due:O}",admin,now);Notify(row.BrandUser,"BRAND","SubmissionOverdue","Đầu việc đã quá hạn",row.Campaign.Title,row.Submission.Id,now);Notify(row.KocUser,"KOC","SubmissionOverdue","Đầu việc đã quá hạn",row.Campaign.Title,row.Submission.Id,now);created++;}else{var previousSeverity=escalation.Severity;if(escalation.Status=="Resolved"){escalation.Status="Open";escalation.AcknowledgedByUserId=null;escalation.AcknowledgedAtUtc=null;escalation.ResolvedByUserId=null;escalation.ResolvedAtUtc=null;History(escalation.Id,"Resolved","Open","Nguồn tái diễn quá hạn",admin,now);}else if(previousSeverity!=severity){History(escalation.Id,escalation.Status,escalation.Status,$"Mức độ tăng {previousSeverity} → {severity}",admin,now);}escalation.LastDetectedAtUtc=now;escalation.Severity=severity;escalation.UpdatedAtUtc=now;}}
        foreach(var escalation in existing.Where(x=>x.Status!="Resolved"&&!overdueIds.Contains(x.SourceEntityId))){var from=escalation.Status;escalation.Status="Resolved";escalation.ResolvedByUserId=admin;escalation.ResolvedAtUtc=now;escalation.UpdatedAtUtc=now;History(escalation.Id,from,"Resolved","Nguồn không còn quá hạn tại lần quét",admin,now);resolved++;}
        var completed=DateTime.UtcNow;var critical=overdue.Count(x=>completed-x.Due>=TimeSpan.FromHours(policy.CriticalAfterHours));db.OperationalScanRuns.Add(new(){Id=Guid.NewGuid(),RuleCode="SUBMISSION_OVERDUE",ActorUserId=admin,StartedAtUtc=now,CompletedAtUtc=completed,DetectedCount=overdue.Count,CreatedCount=created,ResolvedCount=resolved,CriticalCount=critical,CreatedAtUtc=completed});Audit(admin,"OperationalEscalation",Guid.Empty,"ScanSubmissionOverdue",new{Created=created,Resolved=resolved,Detected=overdue.Count,Critical=critical,Policy=new{policy.HighAfterHours,policy.CriticalAfterHours}},completed);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok($"Đã quét {overdue.Count} đầu việc quá hạn: tạo {created}, tự đóng {resolved} escalation.");
    }
    public async Task<OperationsResult> AcknowledgeEscalationAsync(Guid admin,Guid id,string note,CancellationToken ct=default)
    {
        note=Clean(note)??"";if(note.Length is <5 or >1000)return Fail("Ghi chú tiếp nhận từ 5–1.000 ký tự.");var item=await db.OperationalEscalations.FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Fail("Không tìm thấy escalation.");if(item.Status!="Open")return Fail("Chỉ escalation Open mới được tiếp nhận.");var now=DateTime.UtcNow;item.Status="Acknowledged";item.AcknowledgedByUserId=admin;item.AcknowledgedAtUtc=now;item.UpdatedAtUtc=now;History(id,"Open","Acknowledged",note,admin,now);Audit(admin,"OperationalEscalation",id,"Acknowledge",new{Note=note},now);try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Fail("Escalation vừa thay đổi. Vui lòng tải lại.");}return Ok("Đã tiếp nhận escalation và lưu vào timeline.");
    }
    public async Task<OperationsResult> ScanBrandReviewSlaAsync(Guid admin,CancellationToken ct=default)
    {
        var policy=await db.OperationalSlaPolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.RuleCode=="BRAND_REVIEW_SLA",ct);if(policy is null)return Fail("Chưa có cấu hình SLA duyệt bài. Vui lòng chạy migration 50.");if(!policy.IsActive)return Fail("Rule Brand review SLA đang tạm dừng.");var started=DateTime.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var cutoff=started.AddHours(-policy.HighAfterHours);var stale=await(from s in db.Submissions join p in db.Participations on s.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id where s.Status=="Submitted"&&s.SubmittedAtUtc.HasValue&&s.SubmittedAtUtc<=cutoff&&c.Status=="InProgress" select new{Submission=s,Campaign=c,BrandUser=b.UserId}).ToListAsync(ct);var staleIds=stale.Select(x=>x.Submission.Id).ToHashSet();var existing=await db.OperationalEscalations.Where(x=>x.RuleCode=="BRAND_REVIEW_SLA").ToListAsync(ct);var created=0;var resolved=0;
        foreach(var row in stale){var item=existing.FirstOrDefault(x=>x.SourceEntityId==row.Submission.Id);var submitted=row.Submission.SubmittedAtUtc!.Value;var severity=OperationalSlaRules.Severity(submitted,started,policy.CriticalAfterHours);if(item is null){item=new(){Id=Guid.NewGuid(),RuleCode="BRAND_REVIEW_SLA",SourceEntityType="Submission",SourceEntityId=row.Submission.Id,SubmissionId=row.Submission.Id,Severity=severity,Status="Open",FirstDetectedAtUtc=started,LastDetectedAtUtc=started,CreatedAtUtc=started};db.OperationalEscalations.Add(item);History(item.Id,null,"Open",$"Brand chưa phản hồi bài nộp từ {submitted:O}",admin,started);Notify(row.BrandUser,"BRAND","BrandReviewSla","Bài nộp đang chờ phản hồi quá SLA",row.Campaign.Title,row.Submission.Id,started);created++;}else{var old=item.Severity;if(item.Status=="Resolved"){item.Status="Open";item.AcknowledgedByUserId=null;item.AcknowledgedAtUtc=null;item.ResolvedByUserId=null;item.ResolvedAtUtc=null;History(item.Id,"Resolved","Open","Bài nộp mới tiếp tục quá SLA",admin,started);}else if(old!=severity)History(item.Id,item.Status,item.Status,$"Mức độ tăng {old} → {severity}",admin,started);item.Severity=severity;item.LastDetectedAtUtc=started;item.UpdatedAtUtc=started;}}
        foreach(var item in existing.Where(x=>x.Status!="Resolved"&&!staleIds.Contains(x.SourceEntityId))){var from=item.Status;item.Status="Resolved";item.ResolvedByUserId=admin;item.ResolvedAtUtc=started;item.UpdatedAtUtc=started;History(item.Id,from,"Resolved","Brand đã phản hồi hoặc submission không còn chờ duyệt",admin,started);resolved++;}var completed=DateTime.UtcNow;var critical=stale.Count(x=>OperationalSlaRules.Severity(x.Submission.SubmittedAtUtc!.Value,completed,policy.CriticalAfterHours)=="Critical");db.OperationalScanRuns.Add(new(){Id=Guid.NewGuid(),RuleCode="BRAND_REVIEW_SLA",ActorUserId=admin,StartedAtUtc=started,CompletedAtUtc=completed,DetectedCount=stale.Count,CreatedCount=created,ResolvedCount=resolved,CriticalCount=critical,CreatedAtUtc=completed});Audit(admin,"OperationalEscalation",Guid.Empty,"ScanBrandReviewSla",new{Detected=stale.Count,Created=created,Resolved=resolved,Critical=critical,Policy=new{policy.HighAfterHours,policy.CriticalAfterHours}},completed);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok($"Đã quét {stale.Count} bài chờ Brand duyệt: tạo {created}, tự đóng {resolved} escalation.");
    }

    public async Task<OperationsResult> ScanDisputeSlaAsync(Guid admin,CancellationToken ct=default)
    {
        var policy=await db.OperationalSlaPolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.RuleCode=="DISPUTE_SLA",ct);if(policy is null)return Fail("Chưa có cấu hình SLA cho dispute. Vui lòng chạy migration 47.");if(!policy.IsActive)return Fail("Rule Dispute SLA đang tạm dừng.");var started=DateTime.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var cases=await db.DisputeCases.Where(x=>x.IsActive&&(x.Status=="Open"||x.Status=="InReview")).ToListAsync(ct);var ids=cases.Select(x=>x.Id).ToArray();var lastMessages=await db.DisputeMessages.AsNoTracking().Where(x=>ids.Contains(x.DisputeCaseId)).GroupBy(x=>x.DisputeCaseId).Select(g=>new{Id=g.Key,Last=g.Max(x=>x.CreatedAtUtc)}).ToDictionaryAsync(x=>x.Id,x=>x.Last,ct);var stale=cases.Select(x=>new{Case=x,LastActivity=lastMessages.GetValueOrDefault(x.Id,x.UpdatedAtUtc??x.CreatedAtUtc)}).Where(x=>started-x.LastActivity>=TimeSpan.FromHours(policy.HighAfterHours)).ToList();var staleIds=stale.Select(x=>x.Case.Id).ToHashSet();var existing=await db.OperationalEscalations.Where(x=>x.RuleCode=="DISPUTE_SLA").ToListAsync(ct);var created=0;var resolved=0;
        foreach(var row in stale){var item=existing.FirstOrDefault(x=>x.SourceEntityId==row.Case.Id);var severity=started-row.LastActivity>=TimeSpan.FromHours(policy.CriticalAfterHours)?"Critical":"High";if(item is null){item=new(){Id=Guid.NewGuid(),RuleCode="DISPUTE_SLA",SourceEntityType="DisputeCase",SourceEntityId=row.Case.Id,DisputeCaseId=row.Case.Id,Severity=severity,Status="Open",FirstDetectedAtUtc=started,LastDetectedAtUtc=started,CreatedAtUtc=started};db.OperationalEscalations.Add(item);History(item.Id,null,"Open",$"Không có hoạt động từ {row.LastActivity:O}",admin,started);Notify(row.Case.AssignedAdminUserId??admin,"ADMIN","DisputeSla","Tranh chấp quá SLA",row.Case.Subject,"DisputeCase",row.Case.Id,started);created++;}else{var old=item.Severity;if(item.Status=="Resolved"){item.Status="Open";item.AcknowledgedByUserId=null;item.AcknowledgedAtUtc=null;item.ResolvedByUserId=null;item.ResolvedAtUtc=null;History(item.Id,"Resolved","Open","Tranh chấp tái diễn quá SLA",admin,started);}else if(old!=severity){History(item.Id,item.Status,item.Status,$"Mức độ tăng {old} → {severity}",admin,started);}item.Severity=severity;item.LastDetectedAtUtc=started;item.UpdatedAtUtc=started;}}
        foreach(var item in existing.Where(x=>x.Status!="Resolved"&&!staleIds.Contains(x.SourceEntityId))){var from=item.Status;item.Status="Resolved";item.ResolvedByUserId=admin;item.ResolvedAtUtc=started;item.UpdatedAtUtc=started;History(item.Id,from,"Resolved","Dispute đã có hoạt động mới hoặc kết thúc",admin,started);resolved++;}
        var completed=DateTime.UtcNow;var critical=stale.Count(x=>completed-x.LastActivity>=TimeSpan.FromHours(policy.CriticalAfterHours));db.OperationalScanRuns.Add(new(){Id=Guid.NewGuid(),RuleCode="DISPUTE_SLA",ActorUserId=admin,StartedAtUtc=started,CompletedAtUtc=completed,DetectedCount=stale.Count,CreatedCount=created,ResolvedCount=resolved,CriticalCount=critical,CreatedAtUtc=completed});Audit(admin,"OperationalEscalation",Guid.Empty,"ScanDisputeSla",new{Detected=stale.Count,Created=created,Resolved=resolved,Critical=critical,Policy=new{policy.HighAfterHours,policy.CriticalAfterHours}},completed);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok($"Đã quét {stale.Count} tranh chấp quá SLA: tạo {created}, tự đóng {resolved} escalation.");
    }
    public async Task<OperationsResult> UpdateSlaPolicyAsync(Guid admin,Guid id,int highAfterHours,int criticalAfterHours,bool isActive,string note,CancellationToken ct=default)
    {
        note=Clean(note)??"";if(!OperationalSlaRules.IsValidThresholds(highAfterHours,criticalAfterHours))return Fail("Ngưỡng phải từ 0–2.160 giờ và Critical phải lớn hơn High.");if(note.Length is <5 or >1000)return Fail("Lý do thay đổi phải từ 5–1.000 ký tự.");var item=await db.OperationalSlaPolicies.FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Fail("Không tìm thấy cấu hình SLA.");if(item.HighAfterHours==highAfterHours&&item.CriticalAfterHours==criticalAfterHours&&item.IsActive==isActive)return Fail("Cấu hình không có thay đổi.");var now=DateTime.UtcNow;db.OperationalSlaPolicyHistories.Add(new(){Id=Guid.NewGuid(),PolicyId=item.Id,FromHighAfterHours=item.HighAfterHours,FromCriticalAfterHours=item.CriticalAfterHours,FromIsActive=item.IsActive,ToHighAfterHours=highAfterHours,ToCriticalAfterHours=criticalAfterHours,ToIsActive=isActive,Note=note,ActorUserId=admin,CreatedAtUtc=now});var before=new{item.HighAfterHours,item.CriticalAfterHours,item.IsActive};item.HighAfterHours=highAfterHours;item.CriticalAfterHours=criticalAfterHours;item.IsActive=isActive;item.UpdatedByUserId=admin;item.UpdatedAtUtc=now;Audit(admin,"OperationalSlaPolicy",item.Id,"Update",new{Before=before,After=new{highAfterHours,criticalAfterHours,isActive},Note=note},now);try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Fail("Cấu hình vừa được Admin khác cập nhật. Vui lòng tải lại.");}return Ok("Đã cập nhật SLA và lưu một phiên bản lịch sử mới.");
    }
    private void History(Guid id,string? from,string to,string note,Guid actor,DateTime now)=>db.OperationalEscalationHistories.Add(new(){Id=Guid.NewGuid(),EscalationId=id,FromStatus=from,ToStatus=to,Note=note,ActorUserId=actor,CreatedAtUtc=now});
    private void Notify(Guid user,string audienceRole,string type,string title,string body,Guid sourceId,DateTime now)=>db.Notifications.Add(NotificationFactory.Create(user,type,title,body,now,"Submission",sourceId,audienceRole:audienceRole));
    private void Notify(Guid user,string audienceRole,string type,string title,string body,string sourceType,Guid sourceId,DateTime now)=>db.Notifications.Add(NotificationFactory.Create(user,type,title,body,now,sourceType,sourceId,audienceRole:audienceRole));
    private void Audit(Guid actor,string entity,Guid id,string action,object payload,DateTime now)=>db.AuditLogs.Add(new(){ActorUserId=actor,EntityName=entity,EntityId=id.ToString(),ActionName=action,PayloadJson=JsonSerializer.Serialize(payload),CreatedAtUtc=now});
    private static string? Clean(string? s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();private static OperationsResult Ok(string m)=>new(true,m);private static OperationsResult Fail(string m)=>new(false,m);
}
